TC.samples.dodge = `; ============================================================
; DODGE for the TC-8
; You are the white block on the bottom row. Green blocks fall
; from random columns; dodge them. Each block that falls past
; the bottom scores 1. Every 8 points the blocks fall faster.
; Controls: KEY 3=left 4=right. After game over, any key restarts.
; ============================================================

; ---- memory-mapped I/O ----
.equ KEY,    0xF0        ; last key, clears on read
.equ RNG,    0xF1        ; next random byte (never 0)
.equ FRAME,  0xF2        ; +1 every 2000 instructions
.equ SCORE,  0xF3        ; shown by the UI

; ---- game data in RAM ----
.equ BX,     0x20        ; x of block slots 0..3
.equ BY,     0x24        ; y of block slots 0..3 (FREE = slot unused)
.equ PX,     0x30        ; player x (row 15)
.equ SPAWN,  0x31        ; steps until the next block appears
.equ DELAY,  0x32        ; frames left until the next step
.equ LASTF,  0x33        ; last FRAME value seen
.equ PERIOD, 0x34        ; frames per step right now (shrinks with score)

; ---- tuning ----
.equ STEP_FRAMES, 6      ; frames per step at the start (bigger = slower)
.equ SPAWN_STEPS, 3      ; a new block every this many steps
.equ MAXB,   4           ; at most 4 blocks at once
.equ FREE,   0xFF        ; marks an unused slot
.equ BOTTOM, 240         ; screen address of row 15, x = 0

start:
        CALL init_game

; ------------------------------------------------------------
; Main loop: move the player on every key; step on the timer
; ------------------------------------------------------------
main:
        LDA  R0, [KEY]          ; reading KEY also clears it
        LDI  R4, 0xFF           ; R4 = delta: -1 (left)
        CMPI R0, 3
        JZ   do_move
        LDI  R4, 1              ; +1 (right)
        CMPI R0, 4
        JNZ  no_key
do_move:
        CALL move_player
no_key:
        LDA  R0, [FRAME]        ; wait until FRAME changes
        LDA  R1, [LASTF]
        CMP  R0, R1
        JZ   main
        STA  [LASTF], R0
        LDA  R0, [DELAY]        ; count down frames
        SUBI R0, 1
        STA  [DELAY], R0
        JNZ  main
        LDA  R0, [PERIOD]       ; reload (PERIOD shrinks as the score grows)
        STA  [DELAY], R0
        CALL game_step
        JMP  main

; ------------------------------------------------------------
; init_game: reset everything and draw the player
; ------------------------------------------------------------
init_game:
        CALL clear_screen
        LDI  R0, 0
        STA  [SCORE], R0
        LDI  R0, 7
        STA  [PX], R0           ; player starts mid-row
        LDI  R0, FREE           ; all block slots empty
        STA  [BY], R0
        STA  [BY+1], R0
        STA  [BY+2], R0
        STA  [BY+3], R0
        LDI  R0, SPAWN_STEPS
        STA  [SPAWN], R0
        LDI  R0, STEP_FRAMES
        STA  [PERIOD], R0
        STA  [DELAY], R0
        LDA  R0, [FRAME]
        STA  [LASTF], R0
        LDI  R2, 3              ; white
        CALL paint_player
        RET

; ------------------------------------------------------------
; clear_screen: VRAM[0..255] = 0
; ------------------------------------------------------------
clear_screen:
        LDI  R0, 0
        LDI  R1, 0
cs_loop:
        VST  [R0], R1
        ADDI R0, 1
        JNC  cs_loop            ; carry when R0 wraps 255 -> 0
        RET

; ------------------------------------------------------------
; paint_player: paint the player's cell with color R2 (uses R1)
; ------------------------------------------------------------
paint_player:
        LDA  R1, [PX]
        ADDI R1, BOTTOM
        VST  [R1], R2
        RET

; ------------------------------------------------------------
; move_player: move by R4 (+1 / -1), clamped to the screen.
; Moving into a falling block ends the game.
; ------------------------------------------------------------
move_player:
        LDA  R1, [PX]
        CMPI R4, 1
        JZ   mp_right
        CMPI R1, 0              ; moving left: stop at x = 0
        JZ   mp_done
        JMP  mp_go
mp_right:
        CMPI R1, 15             ; moving right: stop at x = 15
        JZ   mp_done
mp_go:
        LDI  R2, 0
        CALL paint_player       ; erase the old cell
        LDA  R1, [PX]
        ADD  R1, R4
        STA  [PX], R1
        ADDI R1, BOTTOM
        VLD  R3, [R1]           ; is a block sitting there?
        CMPI R3, 1
        JZ   mp_dead
        LDI  R2, 3
        CALL paint_player       ; draw at the new cell
mp_done:
        RET
mp_dead:
        CALL game_over
        RET

; ------------------------------------------------------------
; slot_load: R6 = slot -> R1 = x, R2 = y (FREE if unused),
;            R3 = screen address y*16 + x
; ------------------------------------------------------------
slot_load:
        MOV  R3, R6
        ADDI R3, BX
        LD   R1, [R3]
        MOV  R3, R6
        ADDI R3, BY
        LD   R2, [R3]
        MOV  R3, R2
        SHL  R3
        SHL  R3
        SHL  R3
        SHL  R3
        ADD  R3, R1
        RET

; slot_store_y: BY[R6] = R2 (uses R5)
slot_store_y:
        MOV  R5, R6
        ADDI R5, BY
        ST   [R5], R2
        RET

; ------------------------------------------------------------
; game_step: blocks fall one row; score misses; maybe spawn
; Pass 1 erases every block, pass 2 moves and repaints them, so
; two blocks in the same column never erase each other.
; ------------------------------------------------------------
game_step:
        LDI  R6, 0
gs_erase:
        CALL slot_load
        CMPI R2, FREE
        JZ   gs_e_next
        LDI  R5, 0
        VST  [R3], R5
gs_e_next:
        ADDI R6, 1
        CMPI R6, MAXB
        JNZ  gs_erase

        LDI  R6, 0
gs_move:
        CALL slot_load
        CMPI R2, FREE
        JZ   gs_m_next
        ADDI R2, 1              ; one row down
        CMPI R2, 16
        JNZ  gs_m_on
        LDI  R2, FREE           ; fell past the bottom: free the slot...
        CALL slot_store_y
        CALL add_point          ; ...and score it
        JMP  gs_m_next
gs_m_on:
        CALL slot_store_y
        ADDI R3, 16             ; R3 = new screen address
        CMPI R2, 15
        JNZ  gs_m_paint
        LDA  R4, [PX]           ; reached the bottom row: on the player?
        CMP  R4, R1
        JZ   gs_dead
gs_m_paint:
        LDI  R5, 1
        VST  [R3], R5           ; paint green
gs_m_next:
        ADDI R6, 1
        CMPI R6, MAXB
        JNZ  gs_move

        LDA  R0, [SPAWN]        ; time for a new block?
        SUBI R0, 1
        STA  [SPAWN], R0
        JNZ  gs_done
        LDI  R0, SPAWN_STEPS
        STA  [SPAWN], R0
        CALL spawn_block
gs_done:
        RET
gs_dead:
        CALL game_over
        RET

; ------------------------------------------------------------
; add_point: SCORE += 1; PERIOD = STEP_FRAMES - SCORE/8 (min 1)
; ------------------------------------------------------------
add_point:
        LDA  R0, [SCORE]
        ADDI R0, 1
        STA  [SCORE], R0
        SHR  R0                 ; R0 = SCORE / 8
        SHR  R0
        SHR  R0
        LDI  R4, STEP_FRAMES
        SUB  R4, R0
        JC   ap_min             ; would go below zero
        JZ   ap_min             ; or reach zero
        JMP  ap_set
ap_min:
        LDI  R4, 1
ap_set:
        STA  [PERIOD], R4
        RET

; ------------------------------------------------------------
; spawn_block: put a block in a free slot at a random column, row 0
; ------------------------------------------------------------
spawn_block:
        LDI  R6, 0
sb_find:
        MOV  R3, R6
        ADDI R3, BY
        LD   R2, [R3]
        CMPI R2, FREE
        JZ   sb_found
        ADDI R6, 1
        CMPI R6, MAXB
        JNZ  sb_find
        RET                     ; all slots busy: skip this one
sb_found:
        LDI  R2, 0
        ST   [R3], R2           ; y = 0
        LDA  R1, [RNG]
        ANDI R1, 15             ; x = random column
        MOV  R3, R6
        ADDI R3, BX
        ST   [R3], R1
        LDI  R5, 1
        VST  [R1], R5           ; row 0: screen address = x
        RET

; ------------------------------------------------------------
; game_over: paint the screen red, wait for a key, restart
; ------------------------------------------------------------
game_over:
        LDI  R0, 0
        LDI  R1, 2
go_fill:
        VST  [R0], R1
        ADDI R0, 1
        JNC  go_fill
        LDA  R0, [KEY]          ; drop any key pressed while dying
go_wait:
        LDA  R0, [KEY]
        CMPI R0, 0
        JZ   go_wait
        CALL init_game
        RET
`;
if (typeof module !== 'undefined') module.exports = globalThis.TC = TC; else globalThis.TC = TC;
